namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez is a former software architect at Google with deep expertise in algorithm optimization. He earned his Ph.D. from Stanford University.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implement relational databases. Covers SQL, normalization, indexing, transactions, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = false },
            new() { Id = 4, CourseCode = "MATH 101", Title = "Calculus I", Description = "An introduction to differential and integral calculus. Topics include limits, derivatives, integrals, and the Fundamental Theorem of Calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is an award-winning educator specializing in applied mathematics. She received her Ph.D. from Princeton and has authored two widely-used calculus textbooks.", DepartmentId = 2, IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Study vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is an award-winning educator specializing in applied mathematics. She received her Ph.D. from Princeton and has authored two widely-used calculus textbooks.", DepartmentId = 2, IsFeatured = false },
            new() { Id = 6, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. James Wilson", InstructorBio = "Dr. Wilson is a former NASA researcher who brings real-world physics experience to the classroom. He specializes in classical mechanics and astrophysics.", DepartmentId = 3, IsFeatured = true },
            new() { Id = 7, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. James Wilson", InstructorBio = "Dr. Wilson is a former NASA researcher who brings real-world physics experience to the classroom. He specializes in classical mechanics and astrophysics.", DepartmentId = 3, IsFeatured = false },
            new() { Id = 8, CourseCode = "ENG 101", Title = "English Composition", Description = "Develop essential writing skills through essays, research papers, and peer review. Focus on clarity, argument structure, and citation.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. Emily Davis", InstructorBio = "Prof. Davis is a published author and writing coach with over 20 years of experience teaching composition and rhetoric at the university level.", DepartmentId = 4, IsFeatured = false },
            new() { Id = 9, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining cultural and historical contexts.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Prof. Emily Davis", InstructorBio = "Prof. Davis is a published author and writing coach with over 20 years of experience teaching composition and rhetoric at the university level.", DepartmentId = 4, IsFeatured = false },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "A global survey of human civilizations from prehistory through the late medieval period, covering political, economic, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Michael Thompson", InstructorBio = "Dr. Thompson is a historian specializing in cross-cultural exchange. He holds a Ph.D. from Yale and has conducted fieldwork across three continents.", DepartmentId = 5, IsFeatured = false },
            new() { Id = 11, CourseCode = "HIST 202", Title = "Modern World History", Description = "Examine global developments from 1500 to the present, including colonialism, industrialization, world wars, and globalization.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Michael Thompson", InstructorBio = "Dr. Thompson is a historian specializing in cross-cultural exchange. He holds a Ph.D. from Yale and has conducted fieldwork across three continents.", DepartmentId = 5, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

